INSERT INTO `tip_templates` (`id`, `code`, `rule_type`, `title_tpl`, `body_tpl`, `locale`, `is_active`, `created_by`, `created_at`, `updated_at`) VALUES (1,'R1_OVER_BUDGET_1','over_budget','{category} is heading over budget','At your current pace, {category} will go over budget by {amount}. Try setting a weekly cap for the rest of the month.','en',1,NULL,'2026-09-26 10:03:55.110','2026-09-26 10:03:55.110'),(2,'R1_OVER_BUDGET_2','over_budget','Slow down on {category}','You have already used {percent} of your {category} budget. Cutting back a little now could save you {amount}.','en',1,NULL,'2026-09-26 10:03:55.129','2026-09-26 10:03:55.129'),(3,'R2_ABOVE_AVERAGE_1','above_average','{category} spending is up {percent}','You are spending {percent} more on {category} than usual. Bringing it back to your average would save about {amount}.','en',1,NULL,'2026-09-26 10:03:55.149','2026-09-26 10:03:55.149'),(4,'R2_ABOVE_AVERAGE_2','above_average','Unusual month for {category}','This month {category} is well above your normal level. Review recent purchases to find {amount} you could skip.','en',1,NULL,'2026-09-26 10:03:55.168','2026-09-26 10:03:55.168'),(5,'R3_SMALL_FREQUENT_1','small_frequent','Small {category} purchases add up','Lots of small {category} purchases this week add up quickly. Planning ahead could save around {amount}.','en',1,NULL,'2026-09-26 10:03:55.189','2026-09-26 10:03:55.189'),(6,'R3_SMALL_FREQUENT_2','small_frequent','Try a DIY week for {category}','Making coffee or snacks at home instead of buying them could cut your {category} spending by about {amount}.','en',1,NULL,'2026-09-26 10:03:55.208','2026-09-26 10:03:55.208'),(7,'R4_SUBSCRIPTIONS_1','subscriptions','Check your subscriptions','You are paying for several subscriptions. Cancelling the one you use least would save {amount} a month.','en',1,NULL,'2026-09-26 10:03:55.231','2026-09-26 10:03:55.231'),(8,'R4_SUBSCRIPTIONS_2','subscriptions','Share or switch a plan','Student or family plans can be much cheaper. Switching one subscription could save you around {amount}.','en',1,NULL,'2026-09-26 10:03:55.249','2026-09-26 10:03:55.249'),(9,'R5_SAVINGS_GAP_1','savings_gap','You are {amount} short of your savings goal','At this pace you will miss your monthly savings goal by {amount}. Moving money to savings at the start of the month helps.','en',1,NULL,'2026-09-26 10:03:55.270','2026-09-26 10:03:55.270'),(10,'R5_SAVINGS_GAP_2','savings_gap','Close the savings gap','Trimming {category} a little would close most of your {amount} savings gap this month.','en',1,NULL,'2026-09-26 10:03:55.292','2026-09-26 10:03:55.292'),(11,'R6_WEEKEND_SPIKE_1','weekend_spike','Weekends take {percent} of your spending','Your weekend spending was {percent} of the week. Setting a weekend budget could save about {amount}.','en',1,NULL,'2026-09-26 10:03:55.310','2026-09-26 10:03:55.310'),(12,'R6_WEEKEND_SPIKE_2','weekend_spike','Plan a low-cost weekend','Free campus events, picnics or movie nights at home can keep weekend costs down by {amount}.','en',1,NULL,'2026-09-26 10:03:55.327','2026-09-26 10:03:55.327'),(13,'R0_GENERAL_1','general','Pay yourself first','Move a fixed amount to savings as soon as your allowance arrives, then spend what is left.','en',1,NULL,'2026-09-26 10:03:55.348','2026-09-26 10:03:55.348'),(14,'R0_GENERAL_2','general','Use your student discount','Always ask for a student discount on transport, software, books and entertainment.','en',1,NULL,'2026-09-26 10:03:55.365','2026-09-26 10:03:55.365'),(15,'R0_GENERAL_3','general','Wait 24 hours before buying','For non-essential purchases, wait a day. If you still want it tomorrow, it is probably worth it.','en',1,NULL,'2026-09-26 10:03:55.382','2026-09-26 10:03:55.382');
